using System.Net; using System.Net.Http.Json; using ConjuntoInteligente.PbBridge.Contracts; using ConjuntoInteligente.PbBridge.Contracts.Dtos; using FluentAssertions; using Microsoft.AspNetCore.Hosting; using Microsoft.AspNetCore.Mvc.Testing; using Microsoft.Extensions.Configuration; using WireMock.Server; using WireMock.RequestBuilders; using WireMock.ResponseBuilders;
namespace ConjuntoInteligente.PbBridge.Tests;
public sealed class ContractTests:IClassFixture<PbBridgeFactory>{private readonly PbBridgeFactory _factory; public ContractTests(PbBridgeFactory factory)=>_factory=factory; private const string DevToken="dev-token-not-for-production-0000";
 [Fact] public async Task Health_does_not_require_token(){var c=_factory.CreateClient();(await c.GetAsync("/health")).StatusCode.Should().Be(HttpStatusCode.OK);}
 [Fact] public async Task Orders_list_without_token_returns_401_envelope(){var c=_factory.CreateClient();var r=await c.PostAsJsonAsync("/pb/v1/orders/list",new PbOrderListRequest());r.StatusCode.Should().Be(HttpStatusCode.Unauthorized);var b=await r.Content.ReadFromJsonAsync<PbResponse<object>>();b!.Ok.Should().BeFalse();b.Code.Should().Be(PbErrorCodes.Unauthorized);}
 [Fact] public async Task Orders_list_with_user_token_returns_pb_envelope(){_factory.CoreMock.Given(Request.Create().WithPath("/api/v1/maintenance/orders").UsingGet().WithHeader("Authorization","Bearer user-jwt")).RespondWith(Response.Create().WithStatusCode(200).WithHeader("Content-Type","application/json").WithBodyAsJson(new{items=new[]{new{id="o-1",code="MT-00000001",title="Falla",category="iluminacion",severity="high",status="in_progress",area_name="Parqueadero 1",zone_name="Zona 3",asset_node_id=(string?)null,reporter_kind="resident",reporter_name="Ana",vendor_name=(string?)null,cost_cop=(decimal?)null,created_at="2026-10-01T12:00:00Z",updated_at="2026-10-01T13:00:00Z",sla_due_at=(string?)null,description=""}},total=1,page=1,page_size=50}));var c=_factory.CreateClient();c.DefaultRequestHeaders.Add("X-PB-Service-Token",DevToken);c.DefaultRequestHeaders.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer","user-jwt");var r=await c.PostAsJsonAsync("/pb/v1/orders/list",new PbOrderListRequest());r.StatusCode.Should().Be(HttpStatusCode.OK);var b=await r.Content.ReadFromJsonAsync<PbResponse<PbOrderListResponse>>();b!.Ok.Should().BeTrue();b.Code.Should().Be("OK");b.Data!.Items.Should().HaveCount(1);b.Data.Items[0].Codigo.Should().Be("MT-00000001");b.Data.Items[0].Estado.Should().Be("in_progress");}
 [Fact] public async Task Core_unavailable_returns_PB_CORE_UNAVAILABLE(){_factory.CoreMock.Reset();_factory.CoreMock.Given(Request.Create().WithPath("/api/v1/maintenance/orders").UsingGet().WithHeader("Authorization","Bearer user-jwt")).RespondWith(Response.Create().WithStatusCode(500));var c=_factory.CreateClient();c.DefaultRequestHeaders.Add("X-PB-Service-Token",DevToken);c.DefaultRequestHeaders.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer","user-jwt");var r=await c.PostAsJsonAsync("/pb/v1/orders/list",new PbOrderListRequest());r.StatusCode.Should().Be(HttpStatusCode.BadGateway);var b=await r.Content.ReadFromJsonAsync<PbResponse<object>>();b!.Code.Should().Be(PbErrorCodes.CoreError);}
 [Fact] public async Task Missing_user_jwt_is_not_replaced_by_a_service_identity(){_factory.CoreMock.Reset();_factory.CoreMock.Given(Request.Create().WithPath("/api/v1/maintenance/orders").UsingGet()).RespondWith(Response.Create().WithStatusCode(401));var c=_factory.CreateClient();c.DefaultRequestHeaders.Add("X-PB-Service-Token",DevToken);var r=await c.PostAsJsonAsync("/pb/v1/orders/list",new PbOrderListRequest());r.StatusCode.Should().Be(HttpStatusCode.Unauthorized);var b=await r.Content.ReadFromJsonAsync<PbResponse<object>>();b!.Code.Should().Be(PbErrorCodes.Unauthorized);}
 [Fact] public async Task Login_returns_user_access_token_from_erp(){_factory.CoreMock.Given(Request.Create().WithPath("/api/v1/auth/login").UsingPost()).RespondWith(Response.Create().WithStatusCode(200).WithHeader("Content-Type","application/json").WithBodyAsJson(new{access_token="signed-user-jwt",token_type="bearer"}));var c=_factory.CreateClient();c.DefaultRequestHeaders.Add("X-PB-Service-Token",DevToken);var r=await c.PostAsJsonAsync("/pb/v1/auth/login",new PbLoginRequest{Email="resident@example.test",Password="password",TenantId="00000000-0000-0000-0000-000000000001"});r.StatusCode.Should().Be(HttpStatusCode.OK);var b=await r.Content.ReadFromJsonAsync<PbResponse<PbLoginResponse>>();b!.Data!.AccessToken.Should().Be("signed-user-jwt");}
 [Fact] public async Task Invalid_porPagina_returns_validation_error(){var c=_factory.CreateClient();c.DefaultRequestHeaders.Add("X-PB-Service-Token",DevToken);var r=await c.PostAsJsonAsync("/pb/v1/orders/list",new PbOrderListRequest{PorPagina=999});r.StatusCode.Should().Be(HttpStatusCode.BadRequest);var b=await r.Content.ReadFromJsonAsync<PbResponse<object>>();b!.Code.Should().Be(PbErrorCodes.ValidationError);}
 [Fact] public async Task Catalogos_endpoint_returns_catalog_envelope(){var c=_factory.CreateClient();c.DefaultRequestHeaders.Add("X-PB-Service-Token",DevToken);var r=await c.GetAsync("/pb/v1/catalogos/estados-orden");r.StatusCode.Should().Be(HttpStatusCode.OK);var b=await r.Content.ReadFromJsonAsync<PbResponse<PbCatalogDto>>();b!.Ok.Should().BeTrue();b.Data!.Dominio.Should().Be("estados-orden");b.Data.Valores.Should().Contain(v=>v.Clave=="in_progress");}}
public sealed class PbBridgeFactory:WebApplicationFactory<Program>,IDisposable{public WireMockServer CoreMock{get;} public PbBridgeFactory(){CoreMock=WireMockServer.Start();} protected override void ConfigureWebHost(IWebHostBuilder builder){builder.UseEnvironment("Development");builder.ConfigureAppConfiguration((_,cfg)=>cfg.AddInMemoryCollection(new Dictionary<string,string?>{{"PB:ServiceToken","dev-token-not-for-production-0000"},{"Core:BaseUrl",CoreMock.Urls[0]},{"Otel:Endpoint","http://localhost:4317"}}));} public new void Dispose(){CoreMock.Stop();CoreMock.Dispose();base.Dispose();}}
